(function () {
  var b64 = "";
  var bytes = Uint8Array.from(atob(b64), function (c) { return c.charCodeAt(0); });
  var html = new TextDecoder("utf-8").decode(bytes);
  var root = document.getElementById("bd-root");
  if (!root || root.querySelector("iframe")) return;
  var f = document.createElement("iframe");
  f.title = "Design your bathroom";
  f.setAttribute("allow", "clipboard-write");
  f.style.cssText = "display:block;width:100%;height:900px;border:0;background:#fff";
  f.srcdoc = html;
  root.appendChild(f);
  window.addEventListener("message", function (e) {
    if (e.source !== f.contentWindow || !e.data || e.data.type !== "bd-height") return;
    f.style.height = e.data.h + "px";
  });
})();
